(function(root){'use strict';
function progress(rows,bank){const valid=bank.map(m=>rows.find(r=>r.id===m.id)),earned=valid.filter(r=>r?.status==='demonstrated').length;return {earned,total:bank.length,remaining:bank.length-earned,complete:bank.length>0&&earned===bank.length};}
function ring(rows,bank){const p=progress(rows,bank);return `<div class="quest-wheel" role="progressbar" aria-label="Skill badges earned" aria-valuemin="0" aria-valuemax="${p.total}" aria-valuenow="${p.earned}" aria-valuetext="${p.earned} of ${p.total} earned; ${p.remaining} remaining"><svg viewBox="0 0 120 120" aria-hidden="true"><circle cx="60" cy="60" r="49" fill="none" stroke="#ced9e8" stroke-width="9"/><circle class="wheel-fill" cx="60" cy="60" r="49" fill="none" stroke="#cc8a00" stroke-width="9" pathLength="100" stroke-dasharray="${p.earned/p.total*100} 100" transform="rotate(-90 60 60)"/>${bank.map((m,i)=>{const a=(i*360/bank.length-90)*Math.PI/180;return `<circle cx="${60+49*Math.cos(a)}" cy="${60+49*Math.sin(a)}" r="3" fill="#fff"/>`}).join('')}</svg><span><b>${p.earned}<small>/${p.total}</small></b><em>badges earned</em></span></div>`;}
function panel(rows,bank,compact=false){const p=progress(rows,bank);return `<section class="quest-progress ${compact?'compact':''}"><div class="quest-progress-main">${ring(rows,bank)}<div><p class="eyebrow">YOUR BADGE COLLECTION</p><h3>${p.complete?'Collection complete!':`${p.remaining} badge${p.remaining===1?'':'s'} to go`}</h3><p>${p.complete?'All eight skills demonstrated. Your trophy and chocolate-bar voucher are unlocked.':'Complete each mission and its delayed follow-up to earn the badge. The collection includes the X-linked extension mission.'}</p>${!compact?`<div class="quest-steps">${bank.map((m,i)=>`<span class="${rows.find(r=>r.id===m.id)?.status==='demonstrated'?'done':''}"><b>${rows.find(r=>r.id===m.id)?.status==='demonstrated'?'✓':i+1}</b>${m.badge}</span>`).join('')}</div>`:''}</div></div>${p.complete?`<div class="quest-reward celebrate">${root.MissionArt.svg('trophy')}<div><p class="eyebrow">SCIENCE STUDIO · ALL EIGHT</p><h3>Your science trophy</h3><p>Print your reward voucher and present it to your teacher to claim one chocolate bar.</p><button type="button" data-print-mission-reward>Print chocolate-bar voucher →</button> <button type="button" data-replay-trophy>Replay celebration</button><p class="small">Your teacher checks the completed badges and signs off redemption. Printing does not reserve or record a chocolate bar.</p></div><div class="reward-confetti" aria-hidden="true">${Array.from({length:12},(_,i)=>`<i style="--i:${i}"></i>`).join('')}</div>`:!compact?`<div class="quest-locked">${root.MissionArt.svg('trophy')}<p><b>Your final reward</b><br>Earn all ${p.total} badges to reveal the animated trophy and print your chocolate-bar voucher.</p></div>`:''}</section>`;}
const api={progress,ring,panel};if(typeof module!=='undefined')module.exports=api;else root.MissionRewards=api;
})(globalThis);
